import React, { useState } from 'react';
import { Menu, MenuItem, ContextMenuTrigger, ContextMenu } from 'react-contextmenu';

function App() {
  const [menuVisible, setMenuVisible] = useState(false);

  const handleContextMenu = (e) => {
    e.preventDefault();
    setMenuVisible(true);
  };

  const handleMenuItemClick = (e, data) => {
    alert(`Clicked on ${data.item}`);
  };

  return (
    <div onContextMenu={handleContextMenu} style={{ width: '100%', height: '100vh' }}>
      <ContextMenuTrigger id="context_menu">
        <div style={{ padding: '20px' }}>Right-click to see the context menu</div>
      </ContextMenuTrigger>

      <ContextMenu id="context_menu" visible={menuVisible}>
        <MenuItem data={{ item: 'Cut' }} onClick={handleMenuItemClick}>Cut</MenuItem>
        <MenuItem data={{ item: 'Copy' }} onClick={handleMenuItemClick}>Copy</MenuItem>
        <MenuItem data={{ item: 'Paste' }} onClick={handleMenuItemClick}>Paste</MenuItem>
      </ContextMenu>
    </div>
  );
}

export default App;
